	double[] x, y;
	int n, w, l;
	Random rnd;

	final int MAX_COUNT = 50;
	final double EPS = 1e-8;

	boolean go(int k) {
		if (k == n) {
			return true;
		}
		for (int IT = 0; IT < MAX_COUNT; IT++) {
			double xx = rnd.nextDouble() * w;
			double yy = rnd.nextDouble() * l;
			int rr = c[k].r;
			boolean ok = true;
			for (int i = 0; i < k; i++) {
				double d = (xx - x[i]) * (xx - x[i]) + (yy - y[i])
