			for (int i = 1; i < n + 1; i++) {
				an[i] = in.nextLong();
			}

			long[] rui = new long[n+1];
			if (an[1] > 0) {
				rui[1] = an[1];
			}
			for (int i = 2; i < n + 1; i++) {
				if (an[i] > 0) {
					rui[i] += rui[i-1]+an[i];
				} else {
					rui[i] += rui[i-1];
				}
			}

			long ans = 0;
