				long tmp = 0;
				tmp += rui[i-1] - rui[0];
				tmp += rui[n] - rui[i+k-1];

				long inside = 0;
				for (int j = i; j < i + k; j++) {
					inside += an[j];
				}
				if (inside > 0) {
					tmp += inside;
				}
				ans = Math.max(ans, tmp);
			}
			out.println(ans);

		}
	}

