public class A {
	int hei, wid;
	char[][] c;

	int[] dx = new int[]{1, 0, -1, 0};
	int[] dy = new int[]{0, 1, 0, -1};
	String dirs = "v>^<";

	String solve() {
		int ans = 0;
		for (int i = 0; i < hei; i++) {
			for (int j = 0; j < wid; j++) {
				if (c[i][j] == '.') {
					continue;
				}
				int ok = 0;
				for (int d = 0; d < 4; d++) {
					int ii = i;
					int jj = j;
					for (;;) {
						ii += dx[d];
						jj += dy[d];
						if (ii < 0 || ii >= hei || jj < 0 || jj >= wid) {
							break;
						}
						if (c[ii][jj] == '.') {
							continue;
						}
						ok |= 1 << d;
						break;
					}
				}
				int d = dirs.indexOf(c[i][j]);
				if ((ok & (1 << d)) != 0) {
					continue;
				}
				if (ok == 0) {
					return "IMPOSSIBLE";
				}
				ans++;
			}
		}
		return "" + ans;
	}

