public class Main {

	public static long MOD = 1000000007;

	public static void main(String[] args) {
		IO io = new IO();
		int n = io.nextInt();
		int m = io.nextInt();
//		long[] dp2 = new long[n+2];
//		for(int i=2;i<=n+1;i++) {
//			dp2[i] = f(i,m);
//			for(int j=i-1;j>=2;j--) {
//				dp2[i] = mod(dp2[i] - dp2[j] * (i - j + 1), MOD);
//			}
//		}
//		long sum = 0;
//		for(int i=2;i<=n+1;i++) {
//			sum += dp2[i];
//		}
//		System.out.println(sum % MOD);
		System.out.println((f(n+1,m) - f(n,m) + MOD) % MOD);
	}

	public static long f(int n,int m) {
		long[][] dp = new long[m*2+1][n];
		for(int i=0;i<n;i++) {
			dp[0][i] = 1;
		}
		for(int i=0;i<m*2;i++) {
			if (i % 2 == 0) {
				for(int j=0;j<n;j++) {
					dp[i+1][j] += dp[i][j];
					if (dp[i+1][j] >= MOD) dp[i+1][j] -= MOD;
					if (j < n - 1) {
						dp[i+1][j+1] += dp[i][j];
						if (dp[i+1][j+1] >= MOD) dp[i+1][j+1] -= MOD;
					}
				}
			}else{
				for(int j=1;j<n;j++) {
					dp[i+1][j-1] += dp[i][j];
					if (dp[i+1][j-1] >= MOD) dp[i+1][j-1] -= MOD;
					dp[i+1][j] += dp[i][j];
					if (dp[i+1][j] >= MOD) dp[i+1][j] -= MOD;
				}
			}
		}
		long sum = 0;
		for(int j=0;j<n;j++) {
			sum += dp[m*2][j];
		}
		return sum % MOD;
	}

	private static int mod(long a,long m) {
		a = a % m;
		if (a < 0) a += m;
		return (int) a;
	}

}
