public class C {
	static long value(int i, int m, int b) {
		long n = 1;
		for (int k = 0; k < m; k++) {
			n = n * b + i % 2;
			i /= 2;
		}
		return n * b + 1;
	}
	public static void main(String[] args) throws IOException {
