					sb.append((i & 1 << k) == 0 ? "0" : "1");
				sb.append("11");
				for (int k = 0; k < m; k++)
					sb.append((i & 1 << k) == 0 ? "0" : "1");
				sb.append("1");
				for (int b = 2; b <= 10; b++)
					sb.append(" " + value(i, m, b));
				pw.println(sb);
			}
		}
		pw.close();
	}
