		for (int i = n; i >= 1; --i) {
			if (f[i - 1]) {
				AVLTree.Node v = tree.kth(i);
				System.out.println(v.key);
				tree.delete(v);
			} else if (f[i - 2] && a[i - 1] > 0) {
				AVLTree.Node v = tree.kth(a[i - 1]);
				System.out.println(v.key);
				tree.delete(v);
			} else {
				AVLTree.Node v = tree.kth(a[i - 1] + 1);
				System.out.println(v.key);
				tree.delete(v);
			}
		}
	}

	public static class AVLTree {
		Node root = null;

		Node ceiling(long v) {
			Node node = root;
			while (node != null) {
				if (max(node.left) >= v) {
					node = node.left;
				} else if (node.key >= v)
					return node;
				else
					node = node.right;
			}
			return node;
		}

