      sum += v[n - i];
      if (sum - (c - x[n - i]) * 2 > lsum[i]) {
        lsum[i] = sum - (c - x[n - i]) * 2;
      }
    }

    // Start at 0 and exit at right
    sum = 0;
    for (int right = 0; right < n; right++) {
      sum += v[right];
      long r = sum - x[right];
      if (r > res) res = r;
    }
    // Start at 0, go to right and then back to left, then exit there
    sum = 0;
    for (int left = n - 1; left > 0; left--) {
      sum += v[left];
