	int N, T;
	int[] times;

	void input() {
		N = ni();
		T = ni();

		times = new int[N];

		for (int i = 0; i < N; i ++) {
			times[i] = ni();
		}		
	}


	long solve() {
		//first push began at 0
		long sum   = T;
		long preEnd= T;

		for (int i = 1; i < N; i ++) {

			if (times[i] >= preEnd) {
				preEnd = times[i] + T;
				sum += T;
			}

			else {
				long diff = times[i] - times[i-1];
				preEnd += diff;
				sum += diff;
			}
		}

		return sum;
	}

