import java.io.*;
import java.util.*;

public class Main implements Runnable{

	Scanner in;
	PrintWriter out;

	double EPS = 1e-10;
	// ret -1 no 0 uniq 1 many
	//matrix, equations, x, result
	int Gauss(double[][] a, int n, int m, double[] x)
	{
		int[] was = new int[n];
		Arrays.fill(was, -1);
		for (int i = 0; i < m; i++)
		{
			int k = -1;
			for (int j = 0; j < n; j++)
			if (was[j] == -1 && Math.abs(a[j][i]) > EPS)
			{ k = j; break; }
			if (k == -1)
			continue;
			was[k] = i;
			double t = 1 / a[k][i];
			for (int j = 0; j <= m; j++)
			a[k][j] *= t;
			for (int j = 0; j < n; j++)
			if (j != k)
			{
				double p = -a[j][i];
				for (int h = 0; h <= m; h++)
				a[j][h] += p * a[k][h];
			}
		}
		int flag = 0;
		Arrays.fill(x, 0);
		for (int i = 0; i < n; i++)
		if (was[i] == -1)
		{
			if (Math.abs(a[i][m]) > EPS)
			return -1;
			flag++;
		}
		else
			x[was[i]] = a[i][m];
		if (n - flag == m)
			return 0;
		else
			return 1;
	}

	public void Run()throws IOException
	{
		in = new Scanner(new File("input.txt"));
		out = new PrintWriter("output.txt");

		int nt = in.nextInt();
		in.nextLine();
		for(int it=0;it<nt;it++)
		{
			out.print("Case #" + (it + 1) + ": ");
			double x11 = in.nextInt(), y11 = in.nextInt();
			double x12 = in.nextInt(), y12 = in.nextInt();
